def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit operation to transform s_in to s_out."""
    # Simple approach: find first difference and determine if it's insertion/deletion/substitution
    min_len = min(len(s_in), len(s_out))

    # Look for first differing position
    diff_pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            diff_pos = i
            break

    # If we found a difference
    if diff_pos != -1:
        # Check if we're inserting or deleting
        if len(s_in) < len(s_out):
            # Insertion - pattern is s_in[diff_pos:] 
            return (s_in[diff_pos:], s_out[diff_pos:diff_pos+len(s_in[diff_pos:])], diff_pos)
        elif len(s_in) > len(s_out):
            # Deletion - pattern is s_in[diff_pos:diff_pos+1] 
            return (s_in[diff_pos:diff_pos+1], '', diff_pos)
        else:
            # Substitution
            return (s_in[diff_pos:diff_pos+1], s_out[diff_pos:diff_pos+1], diff_pos)
    else:
        # No difference found - but they should be different based on our filter
        # This shouldn't happen given our filtering, but let's handle edge case
        if len(s_in) < len(s_out):
            # Insertion at end
            return (s_in[-1:] if s_in else '', s_out[len(s_in):], len(s_in))
        elif len(s_in) > len(s_out):
            # Deletion at end
            return (s_in[len(s_out):], '', len(s_out))
        else:
            # Shouldn't happen, but return something
            return ('', '', 0)

